// Dependency-free HTTPS -> HTTP reverse proxy (adds X-Forwarded-*). Usage: node tls-proxy.mjs <listenPort> <targetPort> <certDir>
// certDir holds key.pem/cert.pem generated by run-all.mjs at runtime (never committed).
import https from 'node:https';
import http from 'node:http';
import fs from 'node:fs';
import net from 'node:net';
import path from 'node:path';

const [listenArg, targetArg, certDir] = process.argv.slice(2);
const listen = Number(listenArg);
const target = Number(targetArg);
const opts = { key: fs.readFileSync(path.join(certDir, 'key.pem')), cert: fs.readFileSync(path.join(certDir, 'cert.pem')) };

const srv = https.createServer(opts, (req, res) => {
  const headers = { ...req.headers, 'x-forwarded-proto': 'https', 'x-forwarded-host': req.headers.host, 'x-forwarded-port': String(listen) };
  const up = http.request({ host: '127.0.0.1', port: target, method: req.method, path: req.url, headers }, (r) => {
    res.writeHead(r.statusCode, r.rawHeaders);
    r.pipe(res);
  });
  up.on('error', (e) => {
    if (!res.headersSent) res.writeHead(502);
    res.end('proxy error ' + e.message);
  });
  req.pipe(up);
});
srv.on('upgrade', (req, sock, head) => {
  const u = net.connect(target, '127.0.0.1', () => {
    u.write(`${req.method} ${req.url} HTTP/1.1\r\n` + Object.entries(req.headers).map(([k, v]) => `${k}: ${v}`).join('\r\n') + '\r\n\r\n');
    u.write(head);
    u.pipe(sock);
    sock.pipe(u);
  });
  u.on('error', () => sock.destroy());
});
srv.listen(listen, '127.0.0.1', () => console.log(`tls ${listen} -> ${target}`));
